STEPS=['Start','Components','Plan','Install','Accounts','First project','Checks']
def stepper(cur):
    out='<ol style="margin: 0; padding: 0; list-style: none; display: flex; flex-direction: column; gap: 4px">'
    for i,n in enumerate(STEPS):
        s='done' if i<cur else 'now' if i==cur else 'next'
        dotc={'done':'var(--green)','now':'var(--orange)','next':'var(--bg-elev)'}[s]
        out+=(f'<li style="display: flex; align-items: center; gap: 10px; padding: 8px 10px; border-radius: 6px; {"background: var(--bg-elev);" if s=="now" else ""}"><span style="width: 24px; height: 24px; border-radius: 50%; display: grid; place-items: center; background: {dotc}; color: {"#1a1714" if s!="next" else "var(--text-meta)"}; font-family: var(--mono); font-size: 12px; font-weight: 600">{"✓" if s=="done" else i}</span>'
              f'<span style="font-size: 14px; color: {"var(--text)" if s!="next" else "var(--text-muted)"}; {"font-weight: 600" if s=="now" else ""}">{n}</span></li>')
    return out+'</ol>'
