nav_items=[('Settings',None),('security','Security'),('look','Appearance'),('cfg','Config and hub'),('agents','Agents'),('room','Room # cubilot'),('Admin',None),('checks','Checks'),('components','Components'),('accounts','Accounts'),('projects','Projects'),('backup','Backup'),('updates','Updates')]
